import time
from collections import defaultdict

class QuoteLifecycleManager:
    def __init__(self, timeout_seconds=30):
        self.quotes = defaultdict(lambda: {'status': 'active', 'timestamp': time.time()})
        self.timeout_seconds = timeout_seconds

    def add_quote(self, quote_id):
        if quote_id in self.quotes:
            self.quotes[quote_id]['timestamp'] = time.time()
        else:
            self.quotes[quote_id] = {'status': 'active', 'timestamp': time.time()}

    def update_status(self):
        current_time = time.time()
        for quote_id, quote_info in self.quotes.items():
            if current_time - quote_info['timestamp'] > self.timeout_seconds:
                quote_info['status'] = 'expired'
                self._cancel_quote(quote_id)

    def _cancel_quote(self, quote_id):
        # Simulate cancel logic
        print(f"Quote {quote_id} has been canceled due to timeout.")

    def get_status(self, quote_id):
        return self.quotes.get(quote_id, {'status': 'not found'})

# Example usage
