    qlm = QuoteLifecycleManager(timeout_seconds=10)
    qlm.add_quote("Q12345")
    time.sleep(5)
    print(qlm.get_status("Q12345"))  # Should still be active
    time.sleep(6)
    qlm.update_status()
    print(qlm.get_status("Q12345"))  # Should now be expired", "scan_level": "strict"}}

